import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.map.js";
/*eslint-disable*/
import OverlayComp from "@/components/OverlayComp.vue";
import LineChart from "@/components/Graph/LineChart.vue";
import DonutChart from "@/components/Graph/DonutChart.vue";
import PieChart from "@/components/Graph/PieChart.vue";
import ColoumnChart from "@/components/Graph/ColoumnChart.vue";
import BarChart from "@/components/Graph/BarChart.vue";
import { Buffer } from "buffer";
import SnackBar from "@/components/SnackBar.vue";
import { get_dashboard_details } from "@/graphql/queries.js";
import { formatedatetime } from "@/JsonFiles/DateFormate.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  components: {
    SnackBar,
    BarChart,
    ColoumnChart,
    PieChart,
    DonutChart,
    LineChart,
    OverlayComp
  },
  data() {
    return {
      lastpublished: [],
      SnackBarComponent: {},
      overlay: false,
      activePanel: null,
      htmlContent: "",
      lastPublisedOn: "",
      summaryField: ""
    };
  },
  created() {
    this.get_dashboard();
  },
  methods: {
    getHeaderClass(panelIndex) {
      return this.activePanel === panelIndex ? false : true;
    },
    async get_dashboard() {
      this.overlay = true;
      try {
        let result = await API.graphql(graphqlOperation(get_dashboard_details, {
          dashboard_id: this.$store.getters.GetdashboardDetails.dashboard_id
        }));
        var response = JSON.parse(result.data.get_dashboard_details);
        if (response.Status == "SUCCESS") {
          this.overlay = false;
          if (response.data[0].message_payload != undefined) {
            this.overlay = false;
            let xapikey = response.data[0].message_payload.data;
            if (xapikey == undefined) {
              this.overlay = false;
              this.lastpublished = [];
              this.htmlContent = "";
            } else {
              this.overlay = false;
              const bufferData = Buffer.from(xapikey);
              const strData = bufferData.toString();
              const api = JSON.parse(strData);
              this.lastPublisedOn = this.fetch_value(response.data[0].last_published_on);
              this.summaryField = response.data[0].dashboard_summary == undefined ? "" : response.data[0].dashboard_summary;
              this.lastpublished = this.transformSectionData(api);
            }
          } else {
            this.overlay = false;
            this.lastpublished = [];
            this.htmlContent = "";
            this.overlay = false;
          }
        } else {
          this.overlay = false;
          this.lastpublished = [];
          this.htmlContent = "";
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.data.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.overlay = false;
        this.lastpublished = [];
        this.htmlContent = "";
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    getRandomColor() {
      const letters = "0123456789ABCDEF";
      let color = "#";
      for (let i = 0; i < 6; i++) {
        color += letters[Math.floor(Math.random() * 16)];
      }
      return color;
    },
    fetch_value(val) {
      return formatedatetime(val / 1000);
    },
    transformSectionData(lastdata) {
      return lastdata.map(section => {
        if (section.section_type === "PIE_CHART") {
          return {
            ...section,
            section_value: [{
              type: "pie",
              startAngle: 240,
              yValueFormatString: '##0.00"%"',
              indexLabel: "{label} {y}",
              dataPoints: section.section_value.map(item => ({
                y: Number(item.value),
                label: item.label
              }))
            }]
          };
        } else if (section.section_type === "DONUT_CHART") {
          return {
            ...section,
            section_value: [{
              type: "doughnut",
              startAngle: 60,
              indexLabelFontSize: 17,
              indexLabel: "{label} - #percent%",
              toolTipContent: "<b>{label}:</b> {y} (#percent%)",
              dataPoints: section.section_value.map(item => ({
                y: Number(item.value),
                label: item.label
              }))
            }]
          };
        }
        return section;
      });
    }
  }
};
